volume.script:
var a = BINANCE:0gusdc;
var b = BINANCE:0gusdt;
var c = BINANCE_FUTURES:0gusdt;
var d = BYBIT:0GUSDT;
var e = BYBIT:0GUSDT-SPOT;
var f = HYPERLIQUID:0G-USD;
var g = KRAKEN:0G/USD;
var h = OKEX:0G-USDT-SWAP;
var i = UPBIT:KRW-0G;

if (upColor === 0) {
  if (options.showDelta) {
    upColor = options.upBgColor
    downColor = options.downBgColor
  } else {
    upColor = options.upColor
    downColor = options.downColor
  }
}

var totalVbuy = a.vbuy+b.vbuy+c.vbuy+d.vbuy+e.vbuy+f.vbuy+g.vbuy+h.vbuy+i.vbuy;
var totalVsell = a.vsell+b.vsell+c.vsell+d.vsell+e.vsell+f.vsell+g.vsell+h.vsell+i.vsell;

if (options.showDelta) {
  plothistogram({ time: time, value: Math.abs(totalVbuy-totalVsell), color: totalVbuy - totalVsell > 0 ? options.upColor : options.downColor})
}

plothistogram({ time: time, value: totalVbuy + totalVsell, color: totalVbuy > totalVsell ? upColor : downColor })

cvd-perp.script:
var a = OKEX:0G-USDT-SWAP;
var b = BINANCE_FUTURES:0gusdt;
var c = BYBIT:0GUSDT;
var d = HYPERLIQUID:0G-USD;

line(cum(b.vbuy-b.vsell), title="BINANCE_FUTURES", color="rgb(240, 185, 11)");

line(cum(c.vbuy-c.vsell), title="BYBIT", color="rgb(255, 184, 0)");

line(cum(d.vbuy-d.vsell), title="HYPERLIQUID", color="rgb(0, 255, 194)");

line(cum(a.vbuy-a.vsell), title="OKEX", color="rgb(13, 110, 253)");

line(cum(b.vbuy-b.vsell+c.vbuy-c.vsell+d.vbuy-d.vsell+a.vbuy-a.vsell), title="total", color="rgb(255,25,183)");

cvd-spot.script:
var a = KRAKEN:0G/USD;
var b = BINANCE:0gusdt;
var c = BINANCE:0gusdc;
var d = BYBIT:0GUSDT-SPOT;
var e = UPBIT:KRW-0G;

line(cum(b.vbuy-b.vsell+c.vbuy-c.vsell), title="BINANCE", color="rgb(240, 185, 11)");

line(cum(d.vbuy-d.vsell), title="BYBIT", color="rgb(255, 184, 0)");

line(cum(a.vbuy-a.vsell), title="KRAKEN", color="rgb(92, 46, 145)");

line(cum(e.vbuy-e.vsell), title="UPBIT", color="rgb(52, 144, 220)");

line(cum(b.vbuy-b.vsell+c.vbuy-c.vsell+d.vbuy-d.vsell+a.vbuy-a.vsell+e.vbuy-e.vsell), title="total", color="rgb(255,25,183)");

vwap.script:
var src = ($price.high + $price.low + $price.close)/3
var vol=vbuy+vsell
var sumVol = cum(vol)
var sumSrcVol = cum(src * vol)
var sumSrcSrcVol = cum(vol*Math.pow(src, 2))
var VWAP = sumSrcVol / sumVol 
var variance = sumSrcSrcVol / sumVol - Math.pow(VWAP, 2)
var stDev = Math.sqrt(variance < 0 ? 0 : variance)

line(VWAP)
cloudarea(VWAP - stDev * options.stdevMultiplier, VWAP + stDev * options.stdevMultiplier)

var unixDays = bar.timestamp / 60 / 60 / 24 + 3
if (unixDays % (options.sessionLengthInDays) === 0) {
  fns[0].state = {}
  fns[1].state = {}
  fns[2].state = {}
}

