line(cum(a.vbuy-a.vsell), title="KRAKEN", color="rgb(92, 46, 145)");

line(cum(b.vbuy-b.vsell), title="OKEX", color="rgb(13, 110, 253)");

line(cum(c.vbuy-c.vsell+d.vbuy-d.vsell+e.vbuy-e.vsell+a.vbuy-a.vsell+b.vbuy-b.vsell), title="total", color="rgb(255,25,183)");

