volume.script:
var a = BINANCE:biousdc;
var b = BINANCE:biousdt;
var c = BINANCE_FUTURES:biousdc;
var d = BINANCE_FUTURES:biousdt;
var e = BITSTAMP:biousd;
var f = BYBIT:BIOUSDT;
var g = COINBASE:BIO-USD;
var h = COINBASE:BIO-USDC;
var i = HYPERLIQUID:BIO-USD;
var j = KRAKEN:BIO/USD;
var k = KRAKEN:PF_BIOUSD;
var l = OKEX:BIO-USD;
var m = OKEX:BIO-USDC;
var n = OKEX:BIO-USDT;
var o = OKEX:BIO-USDT-SWAP;
var p = UPBIT:KRW-BIO;

if (upColor === 0) {
  if (options.showDelta) {
    upColor = options.upBgColor
    downColor = options.downBgColor
  } else {
    upColor = options.upColor
    downColor = options.downColor
  }
}

var totalVbuy = a.vbuy+b.vbuy+c.vbuy+d.vbuy+e.vbuy+f.vbuy+g.vbuy+h.vbuy+i.vbuy+j.vbuy+k.vbuy+l.vbuy+m.vbuy+n.vbuy+o.vbuy+p.vbuy;
var totalVsell = a.vsell+b.vsell+c.vsell+d.vsell+e.vsell+f.vsell+g.vsell+h.vsell+i.vsell+j.vsell+k.vsell+l.vsell+m.vsell+n.vsell+o.vsell+p.vsell;

if (options.showDelta) {
  plothistogram({ time: time, value: Math.abs(totalVbuy-totalVsell), color: totalVbuy - totalVsell > 0 ? options.upColor : options.downColor})
}

plothistogram({ time: time, value: totalVbuy + totalVsell, color: totalVbuy > totalVsell ? upColor : downColor })

