volume.script:
var a = BINANCE:bntusdt;
var b = BINANCE_FUTURES:bntusdt;
var c = BYBIT:BNTUSDT;
var d = COINBASE:BNT-USD;
var e = COINBASE:BNT-USDC;
var f = HYPERLIQUID:BNT-USD;
var g = KRAKEN:BNT/USD;
var h = KRAKEN:PF_BNTUSD;
var i = OKEX:BNT-USD;
var j = OKEX:BNT-USDC;
var k = OKEX:BNT-USDT;

if (upColor === 0) {
  if (options.showDelta) {
    upColor = options.upBgColor
    downColor = options.downBgColor
  } else {
    upColor = options.upColor
    downColor = options.downColor
  }
}

var totalVbuy = a.vbuy+b.vbuy+c.vbuy+d.vbuy+e.vbuy+f.vbuy+g.vbuy+h.vbuy+i.vbuy+j.vbuy+k.vbuy;
var totalVsell = a.vsell+b.vsell+c.vsell+d.vsell+e.vsell+f.vsell+g.vsell+h.vsell+i.vsell+j.vsell+k.vsell;

if (options.showDelta) {
  plothistogram({ time: time, value: Math.abs(totalVbuy-totalVsell), color: totalVbuy - totalVsell > 0 ? options.upColor : options.downColor})
}

plothistogram({ time: time, value: totalVbuy + totalVsell, color: totalVbuy > totalVsell ? upColor : downColor })

cvd-perp.script:
var a = KRAKEN:PF_BNTUSD;
var b = BINANCE_FUTURES:bntusdt;
var c = BYBIT:BNTUSDT;
var d = HYPERLIQUID:BNT-USD;

line(cum(b.vbuy-b.vsell), title="BINANCE_FUTURES", color="rgb(240, 185, 11)");

line(cum(c.vbuy-c.vsell), title="BYBIT", color="rgb(255, 184, 0)");

line(cum(d.vbuy-d.vsell), title="HYPERLIQUID", color="rgb(0, 255, 194)");

line(cum(a.vbuy-a.vsell), title="KRAKEN", color="rgb(92, 46, 145)");

line(cum(b.vbuy-b.vsell+c.vbuy-c.vsell+d.vbuy-d.vsell+a.vbuy-a.vsell), title="total", color="rgb(255,25,183)");

cvd-spot.script:
var a = KRAKEN:BNT/USD;
var b = OKEX:BNT-USD;
var c = OKEX:BNT-USDT;
var d = OKEX:BNT-USDC;
var e = BINANCE:bntusdt;
var f = COINBASE:BNT-USD;
var g = COINBASE:BNT-USDC;

line(cum(e.vbuy-e.vsell), title="BINANCE", color="rgb(240, 185, 11)");

line(cum(f.vbuy-f.vsell+g.vbuy-g.vsell), title="COINBASE", color="rgb(0, 82, 255)");

line(cum(a.vbuy-a.vsell), title="KRAKEN", color="rgb(92, 46, 145)");

line(cum(b.vbuy-b.vsell+c.vbuy-c.vsell+d.vbuy-d.vsell), title="OKEX", color="rgb(13, 110, 253)");

line(cum(e.vbuy-e.vsell+f.vbuy-f.vsell+g.vbuy-g.vsell+a.vbuy-a.vsell+b.vbuy-b.vsell+c.vbuy-c.vsell+d.vbuy-d.vsell), title="total", color="rgb(255,25,183)");

vwap.script:
var src = ($price.high + $price.low + $price.close)/3
var vol=vbuy+vsell
var sumVol = cum(vol)
var sumSrcVol = cum(src * vol)
var sumSrcSrcVol = cum(vol*Math.pow(src, 2))
var VWAP = sumSrcVol / sumVol 
var variance = sumSrcSrcVol / sumVol - Math.pow(VWAP, 2)
var stDev = Math.sqrt(variance < 0 ? 0 : variance)

line(VWAP)
cloudarea(VWAP - stDev * options.stdevMultiplier, VWAP + stDev * options.stdevMultiplier)

var unixDays = bar.timestamp / 60 / 60 / 24 + 3
if (unixDays % (options.sessionLengthInDays) === 0) {
  fns[0].state = {}
  fns[1].state = {}
  fns[2].state = {}
}

