volume.script:
var a = BINANCE:jupusdc;
var b = BINANCE:jupusdt;
var c = BINANCE_FUTURES:jupusdt;
var d = BITFINEX:JUPUSD;
var e = BITFINEX:JUPUST;
var f = BITSTAMP:jupusd;
var g = BYBIT:JUPUSDC-SPOT;
var h = BYBIT:JUPUSDT;
var i = BYBIT:JUPUSDT-SPOT;
var j = HYPERLIQUID:JUP-USD;
var k = KRAKEN:JUP/USD;
var l = KRAKEN:PF_JUPUSD;
var m = OKEX:JUP-USD;
var n = OKEX:JUP-USDC;
var o = OKEX:JUP-USDT;
var p = OKEX:JUP-USDT-SWAP;
var q = UPBIT:KRW-JUP;

if (upColor === 0) {
  if (options.showDelta) {
    upColor = options.upBgColor
    downColor = options.downBgColor
  } else {
    upColor = options.upColor
    downColor = options.downColor
  }
}

var totalVbuy = a.vbuy+b.vbuy+c.vbuy+d.vbuy+e.vbuy+f.vbuy+g.vbuy+h.vbuy+i.vbuy+j.vbuy+k.vbuy+l.vbuy+m.vbuy+n.vbuy+o.vbuy+p.vbuy+q.vbuy;
var totalVsell = a.vsell+b.vsell+c.vsell+d.vsell+e.vsell+f.vsell+g.vsell+h.vsell+i.vsell+j.vsell+k.vsell+l.vsell+m.vsell+n.vsell+o.vsell+p.vsell+q.vsell;

if (options.showDelta) {
  plothistogram({ time: time, value: Math.abs(totalVbuy-totalVsell), color: totalVbuy - totalVsell > 0 ? options.upColor : options.downColor})
}

plothistogram({ time: time, value: totalVbuy + totalVsell, color: totalVbuy > totalVsell ? upColor : downColor })

cvd-perp.script:
var a = KRAKEN:PF_JUPUSD;
var b = OKEX:JUP-USDT-SWAP;
var c = BINANCE_FUTURES:jupusdt;
var d = BYBIT:JUPUSDT;
var e = HYPERLIQUID:JUP-USD;

line(cum(c.vbuy-c.vsell), title="BINANCE_FUTURES", color="rgb(240, 185, 11)");

line(cum(d.vbuy-d.vsell), title="BYBIT", color="rgb(255, 184, 0)");

line(cum(e.vbuy-e.vsell), title="HYPERLIQUID", color="rgb(0, 255, 194)");

line(cum(a.vbuy-a.vsell), title="KRAKEN", color="rgb(92, 46, 145)");

line(cum(b.vbuy-b.vsell), title="OKEX", color="rgb(13, 110, 253)");

line(cum(c.vbuy-c.vsell+d.vbuy-d.vsell+e.vbuy-e.vsell+a.vbuy-a.vsell+b.vbuy-b.vsell), title="total", color="rgb(255,25,183)");

cvd-spot.script:
var a = KRAKEN:JUP/USD;
var b = OKEX:JUP-USD;
var c = OKEX:JUP-USDT;
var d = OKEX:JUP-USDC;
var e = BINANCE:jupusdt;
var f = BINANCE:jupusdc;
var g = BITFINEX:JUPUSD;
var h = BITFINEX:JUPUST;
var i = BITSTAMP:jupusd;
var j = BYBIT:JUPUSDT-SPOT;
var k = BYBIT:JUPUSDC-SPOT;
var l = UPBIT:KRW-JUP;

line(cum(e.vbuy-e.vsell+f.vbuy-f.vsell), title="BINANCE", color="rgb(240, 185, 11)");

line(cum(g.vbuy-g.vsell+h.vbuy-h.vsell), title="BITFINEX", color="rgb(17, 153, 142)");

line(cum(i.vbuy-i.vsell), title="BITSTAMP", color="rgb(14, 182, 156)");

line(cum(j.vbuy-j.vsell+k.vbuy-k.vsell), title="BYBIT", color="rgb(255, 184, 0)");

line(cum(a.vbuy-a.vsell), title="KRAKEN", color="rgb(92, 46, 145)");

line(cum(b.vbuy-b.vsell+c.vbuy-c.vsell+d.vbuy-d.vsell), title="OKEX", color="rgb(13, 110, 253)");

line(cum(l.vbuy-l.vsell), title="UPBIT", color="rgb(52, 144, 220)");

line(cum(e.vbuy-e.vsell+f.vbuy-f.vsell+g.vbuy-g.vsell+h.vbuy-h.vsell+i.vbuy-i.vsell+j.vbuy-j.vsell+k.vbuy-k.vsell+a.vbuy-a.vsell+b.vbuy-b.vsell+c.vbuy-c.vsell+d.vbuy-d.vsell+l.vbuy-l.vsell), title="total", color="rgb(255,25,183)");

vwap.script:
var src = ($price.high + $price.low + $price.close)/3
var vol=vbuy+vsell
var sumVol = cum(vol)
var sumSrcVol = cum(src * vol)
var sumSrcSrcVol = cum(vol*Math.pow(src, 2))
var VWAP = sumSrcVol / sumVol 
var variance = sumSrcSrcVol / sumVol - Math.pow(VWAP, 2)
var stDev = Math.sqrt(variance < 0 ? 0 : variance)

line(VWAP)
cloudarea(VWAP - stDev * options.stdevMultiplier, VWAP + stDev * options.stdevMultiplier)

var unixDays = bar.timestamp / 60 / 60 / 24 + 3
if (unixDays % (options.sessionLengthInDays) === 0) {
  fns[0].state = {}
  fns[1].state = {}
  fns[2].state = {}
}

