volume.script:
var a = BINANCE:morphousdc;
var b = BINANCE:morphousdt;
var c = BINANCE_FUTURES:morphousdt;
var d = BYBIT:MORPHOUSDT;
var e = BYBIT:MORPHOUSDT-SPOT;
var f = COINBASE:MORPHO-USD;
var g = COINBASE:MORPHO-USDC;
var h = HYPERLIQUID:MORPHO-USD;
var i = KRAKEN:MORPHO/USD;
var j = KRAKEN:PF_MORPHOUSD;
var k = OKEX:MORPHO-USD;
var l = OKEX:MORPHO-USDC;
var m = OKEX:MORPHO-USDT;
var n = OKEX:MORPHO-USDT-SWAP;

if (upColor === 0) {
  if (options.showDelta) {
    upColor = options.upBgColor
    downColor = options.downBgColor
  } else {
    upColor = options.upColor
    downColor = options.downColor
  }
}

var totalVbuy = a.vbuy+b.vbuy+c.vbuy+d.vbuy+e.vbuy+f.vbuy+g.vbuy+h.vbuy+i.vbuy+j.vbuy+k.vbuy+l.vbuy+m.vbuy+n.vbuy;
var totalVsell = a.vsell+b.vsell+c.vsell+d.vsell+e.vsell+f.vsell+g.vsell+h.vsell+i.vsell+j.vsell+k.vsell+l.vsell+m.vsell+n.vsell;

if (options.showDelta) {
  plothistogram({ time: time, value: Math.abs(totalVbuy-totalVsell), color: totalVbuy - totalVsell > 0 ? options.upColor : options.downColor})
}

plothistogram({ time: time, value: totalVbuy + totalVsell, color: totalVbuy > totalVsell ? upColor : downColor })

cvd-perp.script:
var a = KRAKEN:PF_MORPHOUSD;
var b = OKEX:MORPHO-USDT-SWAP;
var c = BINANCE_FUTURES:morphousdt;
var d = BYBIT:MORPHOUSDT;
var e = HYPERLIQUID:MORPHO-USD;

line(cum(c.vbuy-c.vsell), title="BINANCE_FUTURES", color="rgb(240, 185, 11)");

line(cum(d.vbuy-d.vsell), title="BYBIT", color="rgb(255, 184, 0)");

line(cum(e.vbuy-e.vsell), title="HYPERLIQUID", color="rgb(0, 255, 194)");

line(cum(a.vbuy-a.vsell), title="KRAKEN", color="rgb(92, 46, 145)");

line(cum(b.vbuy-b.vsell), title="OKEX", color="rgb(13, 110, 253)");

line(cum(c.vbuy-c.vsell+d.vbuy-d.vsell+e.vbuy-e.vsell+a.vbuy-a.vsell+b.vbuy-b.vsell), title="total", color="rgb(255,25,183)");

cvd-spot.script:
var a = KRAKEN:MORPHO/USD;
var b = OKEX:MORPHO-USD;
var c = OKEX:MORPHO-USDT;
var d = OKEX:MORPHO-USDC;
var e = BINANCE:morphousdt;
var f = BINANCE:morphousdc;
var g = BYBIT:MORPHOUSDT-SPOT;
var h = COINBASE:MORPHO-USD;
var i = COINBASE:MORPHO-USDC;

line(cum(e.vbuy-e.vsell+f.vbuy-f.vsell), title="BINANCE", color="rgb(240, 185, 11)");

line(cum(g.vbuy-g.vsell), title="BYBIT", color="rgb(255, 184, 0)");

line(cum(h.vbuy-h.vsell+i.vbuy-i.vsell), title="COINBASE", color="rgb(0, 82, 255)");

line(cum(a.vbuy-a.vsell), title="KRAKEN", color="rgb(92, 46, 145)");

line(cum(b.vbuy-b.vsell+c.vbuy-c.vsell+d.vbuy-d.vsell), title="OKEX", color="rgb(13, 110, 253)");

line(cum(e.vbuy-e.vsell+f.vbuy-f.vsell+g.vbuy-g.vsell+h.vbuy-h.vsell+i.vbuy-i.vsell+a.vbuy-a.vsell+b.vbuy-b.vsell+c.vbuy-c.vsell+d.vbuy-d.vsell), title="total", color="rgb(255,25,183)");

vwap.script:
var src = ($price.high + $price.low + $price.close)/3
var vol=vbuy+vsell
var sumVol = cum(vol)
var sumSrcVol = cum(src * vol)
var sumSrcSrcVol = cum(vol*Math.pow(src, 2))
var VWAP = sumSrcVol / sumVol 
var variance = sumSrcSrcVol / sumVol - Math.pow(VWAP, 2)
var stDev = Math.sqrt(variance < 0 ? 0 : variance)

line(VWAP)
cloudarea(VWAP - stDev * options.stdevMultiplier, VWAP + stDev * options.stdevMultiplier)

var unixDays = bar.timestamp / 60 / 60 / 24 + 3
if (unixDays % (options.sessionLengthInDays) === 0) {
  fns[0].state = {}
  fns[1].state = {}
  fns[2].state = {}
}

