volume.script:
var a = BINANCE:neirousdc;
var b = BINANCE:neirousdt;
var c = BINANCE_FUTURES:neirousdt;
var d = HYPERLIQUID:kNEIRO-USD;
var e = KRAKEN:NEIRO/USD;
var f = KRAKEN:PF_NEIROUSD;
var g = OKEX:NEIRO-USD;
var h = OKEX:NEIRO-USDC;
var i = OKEX:NEIRO-USDT;
var j = OKEX:NEIRO-USDT-SWAP;

if (upColor === 0) {
  if (options.showDelta) {
    upColor = options.upBgColor
    downColor = options.downBgColor
  } else {
    upColor = options.upColor
    downColor = options.downColor
  }
}

var totalVbuy = a.vbuy+b.vbuy+c.vbuy+(d.vbuy*1000)+e.vbuy+f.vbuy+g.vbuy+h.vbuy+i.vbuy+j.vbuy;
var totalVsell = a.vsell+b.vsell+c.vsell+(d.vsell*1000)+e.vsell+f.vsell+g.vsell+h.vsell+i.vsell+j.vsell;

if (options.showDelta) {
  plothistogram({ time: time, value: Math.abs(totalVbuy-totalVsell), color: totalVbuy - totalVsell > 0 ? options.upColor : options.downColor})
}

plothistogram({ time: time, value: totalVbuy + totalVsell, color: totalVbuy > totalVsell ? upColor : downColor })

cvd-perp.script:
var a = KRAKEN:PF_NEIROUSD;
var b = OKEX:NEIRO-USDT-SWAP;
var c = BINANCE_FUTURES:neirousdt;
var d = HYPERLIQUID:kNEIRO-USD;

line(cum(c.vbuy-c.vsell), title="BINANCE_FUTURES", color="rgb(240, 185, 11)");

line(cum(((d.vbuy-d.vsell)*1000)), title="HYPERLIQUID", color="rgb(0, 255, 194)");

line(cum(a.vbuy-a.vsell), title="KRAKEN", color="rgb(92, 46, 145)");

line(cum(b.vbuy-b.vsell), title="OKEX", color="rgb(13, 110, 253)");

line(cum(c.vbuy-c.vsell+((d.vbuy-d.vsell)*1000)+a.vbuy-a.vsell+b.vbuy-b.vsell), title="total", color="rgb(255,25,183)");

cvd-spot.script:
var a = KRAKEN:NEIRO/USD;
var b = OKEX:NEIRO-USD;
var c = OKEX:NEIRO-USDT;
var d = OKEX:NEIRO-USDC;
var e = BINANCE:neirousdt;
var f = BINANCE:neirousdc;

line(cum(e.vbuy-e.vsell+f.vbuy-f.vsell), title="BINANCE", color="rgb(240, 185, 11)");

line(cum(a.vbuy-a.vsell), title="KRAKEN", color="rgb(92, 46, 145)");

line(cum(b.vbuy-b.vsell+c.vbuy-c.vsell+d.vbuy-d.vsell), title="OKEX", color="rgb(13, 110, 253)");

line(cum(e.vbuy-e.vsell+f.vbuy-f.vsell+a.vbuy-a.vsell+b.vbuy-b.vsell+c.vbuy-c.vsell+d.vbuy-d.vsell), title="total", color="rgb(255,25,183)");

vwap.script:
var src = ($price.high + $price.low + $price.close)/3
var vol=vbuy+vsell
var sumVol = cum(vol)
var sumSrcVol = cum(src * vol)
var sumSrcSrcVol = cum(vol*Math.pow(src, 2))
var VWAP = sumSrcVol / sumVol 
var variance = sumSrcSrcVol / sumVol - Math.pow(VWAP, 2)
var stDev = Math.sqrt(variance < 0 ? 0 : variance)

line(VWAP)
cloudarea(VWAP - stDev * options.stdevMultiplier, VWAP + stDev * options.stdevMultiplier)

var unixDays = bar.timestamp / 60 / 60 / 24 + 3
if (unixDays % (options.sessionLengthInDays) === 0) {
  fns[0].state = {}
  fns[1].state = {}
  fns[2].state = {}
}

