volume.script:
var a = BINANCE:rvnusdc;
var b = BINANCE:rvnusdt;
var c = BINANCE_FUTURES:rvnusdt;
var d = BYBIT:RVNUSDT;
var e = BYBIT:RVNUSDT-SPOT;
var f = OKEX:RVN-USD;
var g = OKEX:RVN-USDC;
var h = OKEX:RVN-USDT;
var i = OKEX:RVN-USDT-SWAP;
var j = UPBIT:KRW-RVN;

if (upColor === 0) {
  if (options.showDelta) {
    upColor = options.upBgColor
    downColor = options.downBgColor
  } else {
    upColor = options.upColor
    downColor = options.downColor
  }
}

var totalVbuy = a.vbuy+b.vbuy+c.vbuy+d.vbuy+e.vbuy+f.vbuy+g.vbuy+h.vbuy+i.vbuy+j.vbuy;
var totalVsell = a.vsell+b.vsell+c.vsell+d.vsell+e.vsell+f.vsell+g.vsell+h.vsell+i.vsell+j.vsell;

if (options.showDelta) {
  plothistogram({ time: time, value: Math.abs(totalVbuy-totalVsell), color: totalVbuy - totalVsell > 0 ? options.upColor : options.downColor})
}

plothistogram({ time: time, value: totalVbuy + totalVsell, color: totalVbuy > totalVsell ? upColor : downColor })

cvd-perp.script:
var a = OKEX:RVN-USDT-SWAP;
var b = BINANCE_FUTURES:rvnusdt;
var c = BYBIT:RVNUSDT;

line(cum(b.vbuy-b.vsell), title="BINANCE_FUTURES", color="rgb(240, 185, 11)");

line(cum(c.vbuy-c.vsell), title="BYBIT", color="rgb(255, 184, 0)");

line(cum(a.vbuy-a.vsell), title="OKEX", color="rgb(13, 110, 253)");

line(cum(b.vbuy-b.vsell+c.vbuy-c.vsell+a.vbuy-a.vsell), title="total", color="rgb(255,25,183)");

cvd-spot.script:
var a = OKEX:RVN-USD;
var b = OKEX:RVN-USDT;
var c = OKEX:RVN-USDC;
var d = BINANCE:rvnusdt;
var e = BINANCE:rvnusdc;
var f = BYBIT:RVNUSDT-SPOT;
var g = UPBIT:KRW-RVN;

line(cum(d.vbuy-d.vsell+e.vbuy-e.vsell), title="BINANCE", color="rgb(240, 185, 11)");

line(cum(f.vbuy-f.vsell), title="BYBIT", color="rgb(255, 184, 0)");

