line(cum(a.vbuy-a.vsell), title="total", color="rgb(255,25,183)");

cvd-spot.script:
var a = OKEX:WAXP-USD;
var b = OKEX:WAXP-USDT;
var c = OKEX:WAXP-USDC;
var d = BINANCE:waxpusdt;
var e = BYBIT:WAXPUSDT-SPOT;
var f = UPBIT:KRW-WAXP;

line(cum(d.vbuy-d.vsell), title="BINANCE", color="rgb(240, 185, 11)");

line(cum(e.vbuy-e.vsell), title="BYBIT", color="rgb(255, 184, 0)");

line(cum(a.vbuy-a.vsell+b.vbuy-b.vsell+c.vbuy-c.vsell), title="OKEX", color="rgb(13, 110, 253)");

line(cum(f.vbuy-f.vsell), title="UPBIT", color="rgb(52, 144, 220)");

line(cum(d.vbuy-d.vsell+e.vbuy-e.vsell+a.vbuy-a.vsell+b.vbuy-b.vsell+c.vbuy-c.vsell+f.vbuy-f.vsell), title="total", color="rgb(255,25,183)");

vwap.script:
var src = ($price.high + $price.low + $price.close)/3
var vol=vbuy+vsell
var sumVol = cum(vol)
var sumSrcVol = cum(src * vol)
var sumSrcSrcVol = cum(vol*Math.pow(src, 2))
var VWAP = sumSrcVol / sumVol 
var variance = sumSrcSrcVol / sumVol - Math.pow(VWAP, 2)
var stDev = Math.sqrt(variance < 0 ? 0 : variance)

line(VWAP)
cloudarea(VWAP - stDev * options.stdevMultiplier, VWAP + stDev * options.stdevMultiplier)

var unixDays = bar.timestamp / 60 / 60 / 24 + 3
if (unixDays % (options.sessionLengthInDays) === 0) {
  fns[0].state = {}
  fns[1].state = {}
  fns[2].state = {}
}

